/// <summary>
/// DAI Document Archive integration parameters
/// </summary>
public class AVADAIParameters extends common
{
}

Method.Source:
/// <summary>
/// Don't allow parameter deletion.
/// </summary>
public void delete()
{
    throw error("@SYS23721");
}

/// <summary>
/// find in table.
/// </summary>
/// <param name = "boolean">boolean </param>
/// <returns>A <c>AVADAIParameters</c> table object.</returns>
public static AVADAIParameters  find(boolean _forupdate = false)
{
    AVADAIParameters        parameter;

    try
    {
        if (_forupdate)
        {
            parameter.selectForUpdate(_forupdate);
        }

        select firstonly parameter
            where parameter.Key == 0;

        if (!parameter && !parameter.isTmp())
        {
            Company::createParameter(parameter);
        }
    }
    catch (Exception::DuplicateKeyException)
    {
        retry;
    }

    return parameter;
}

/// <summary>
/// Remove from cache on update.
/// </summary>
public void update()
{
    super();

    flush AVADAIParameters;
}

/// <summary>
/// find by transDefId.
/// </summary>
/// <param name = "AVAMSQTransfDefId">MSQTransfdefid</param>
/// <param name = ""Boolean"">boolean(optional).</param>
/// <returns>A <c>AVAMSQAzureServiceBusDefinition</c> object.</returns>

public static AVAMSQAzureServiceBusDefinition findByTransfDefId(AVAMSQTransfDefId		 _transDefId, boolean _update = false)
{
    AVAMSQAzureServiceBusDefinition			azureServiceBusDefinition;
    ;

    azureServiceBusDefinition.selectForUpdate(_update);

    select firstonly azureServiceBusDefinition
        where azureServiceBusDefinition.TransfDefId == _transDefId;

    return azureServiceBusDefinition;
}
